package glitch

import data.glitch_lib

key_size_attrs := {"key_size", "key_bits", "key_length", "bit_length", "rsa_bits", "modulus_length", "public_key_size"}

ec_size_attrs := {"ec_bits"}

sym_size_attrs := {"symmetric_key_length"}

weak_algo_names := {"DES", "3DES", "TRIPLE_DES", "RC2", "RC4", "RC5", "Blowfish", "MD5", "SHA1", "SHA-1"}

algo_attrs := {"algorithm", "encryption_algorithm", "cipher_algorithm", "hash_algorithm", "key_algorithm", "signing_algorithm", "signature_hash_algorithm", "certificate_algorithm", "integrity_algorithm", "phase1_encryption", "phase2_encryption"}

tls_attrs := {"ssl_policy", "tls_policy", "security_policy", "min_protocol_version", "minimum_tls_version", "minimum_protocol_version", "protocol_version", "enabled_ssl_protocols", "tls_versions"}

cipher_attrs := {"cipher_suites", "allowed_ciphers", "enabled_ciphers", "cipher", "cipher_suite"}

dh_attrs := {"dh_group", "pfs_group", "kex_algorithms"}

weak_tls_pattern := "(?i)(SSLv?2|SSLv?3|TLSv?1\\.0|TLSv?1\\.1|TLS_1_0|TLS_1_1|TLS10|TLS11)"

weak_cipher_pattern := "(?i)(\\bRC4\\b|\\bDES\\b|3DES|\\bNULL\\b|ANON|EXPORT)"

weak_dh_pattern := "(?i)(\\bgroup[125]\\b|diffie-hellman-group[125]\\b|diffie-hellman-group14\\b)"

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    attr.name == key_size_attrs[_]
    attr.value.ir_type == "Integer"
    attr.value.value < 2048
    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate encryption strength - Asymmetric key size is below the recommended minimum of 2048 bits. (CWE-326)"
    }
}

